class Character_AyamiSudo_PreFestival:
    def __init__(self):
        self.basic_info = {
            "name": "须藤绚深 (Sudō Ayami)",
            "former_surname": "松下 (Matsushita)",
            "age": 17,
            "gender": "female",
            "school_year": "高中一年级（复读/转入），与阳花梨同级但年龄稍大"
        }

        self.nicknames = {
            "current_by_hikari_and_friends": "小绚 (Aya-chan)",
            "past_self_reference_or_by_yuu": "暗 (Yami)"
        }

        self.physical_attributes = {
            "hair": {
                "length": "齐颈短发",
                "style": "利落清爽的短发，发梢略带层次感",
                "color": "墨黑色"
            },
            "eyes": "细长而清澈的墨黑色眼眸，眼神锐利且深邃，被阳花梨形容为“仿佛要将人吸入其中的，漆黑而澄澈的瞳孔”。",
            "face_impression": "容貌漂亮，皮肤白皙通透，气质上带有一种与年龄不符的成熟和疏离感。",
            "clothing_style": "以校服为主。私服风格偏向深色系、设计简洁且注重材质质感，不追求少女的甜美风格，带有成熟和个性化元素。",
            "other_features": "有关于其过往曾有自残行为（割腕）的传闻。"
        }

        self.personality_traits = {
            "core": "外表坚强冷静、内心敏感脆弱的矛盾体 / 曾经的“暗”，如今试图在光明中寻找友情的“小绚”",
            "details": [
                "经历了惨痛的家庭变故和与夕的分手，内心承载着远超同龄人的痛苦和秘密。",
                "表面上可能显得冷淡、毒舌、不易接近，甚至有些玩世不恭，用以掩饰内心的脆弱和不安全感。",
                "对白坂阳花梨的纯粹和执着感到既不适又被吸引，逐渐被其“太阳般”的特质所打动，视其为重要的朋友。",
                "在得知阳花梨的暗恋对象是夕之后，内心陷入巨大的痛苦和挣扎。一方面希望阳花梨幸福，另一方面这段关系也触及她最深的伤痛。",
                "为了保护阳花梨，她选择隐瞒自己与夕的过去，并试图引导阳花梨对夕的感情走向积极的方向。",
                "对命运的残酷有深刻体会，有时会流露出宿命般的无力感和对世界的诅咒。",
                "尽管经历了许多黑暗，但内心深处依然渴望“普通”的生活、真挚的友情，以及被他人真正理解和接纳。",
                "在与阳花梨等朋友的相处中，逐渐学会了表露一部分真实的自己，但核心的创伤依然紧锁。",
                "对过去与夕的那段“天堂般的时光”既怀念又视为“碍事”，情感极为复杂。",
                "有较强的观察力和较高的智商（初中时是优等生），能够看透人心，但也因此更容易受伤。",
                "在学校生活中，有逃避倾向，尤其是在可能触及她痛苦回忆（如夕相关）的场合。"
            ],
            "quirks_and_habits": [
                "在与阳花梨的互动中，偶尔会流露出年长者的姿态或略带“说教”的口吻。",
                "对“暗（Yami）”这个昵称非常敏感，明确表示不希望被除夕以外的人这么称呼。",
                "在情绪不佳或想要逃避时，可能会选择独处或用谎言应付朋友的关心。"
            ]
        }

        self.background_story_elements = {
            "family_tragedy_and_name_change": "本名松下绚深。初二时父亲因癌症去世，母亲很快与有钱但品行恶劣的继父再婚。因不堪继父的虐待（险些被侵犯）及母亲的麻木而离家出走，过着颠沛流离的生活。后设计让父母离婚，继父净身出户，但母亲因此精神崩溃并企图自杀，绚深被迫承担起照顾母亲的全部责任。为了与过去切割及照顾母亲，改随母姓（或新姓）为“须藤”。",
            "first_encounter_with_yuu_and_failed_compensated_dating": "在人生最低谷、因生活所迫而尝试进行“爸爸活”（援助交际）时（高一上学期末，约15-16岁），于约定地点等待“客人”。恰逢刚结束中考入学测试、情绪极度低落到几乎哭泣的高村夕坐在她身旁，导致“客人”因情况不便而未能上前搭话，使得该次“爸爸活”意外中止。这成为了她与高村夕的初次相遇。",
            "past_relationship_with_yuu": "在人生最低谷时（高一上学期末，约15-16岁）与高村夕相遇，两人在扭曲的开端后发展出一段深刻的恋情，经历了第一次（以及后续的许多次）性关系，这段时光曾是她“人生中最幸福的”。但为了照顾精神崩溃的母亲，她在17岁生日当天主动、彻底地切断了与夕的所有联系，称夕为“我抛弃的男人”和“最喜欢的人”。",
            "return_to_school_and_friendship_with_hikari": "与夕分手后，为了逃避与母亲在家24小时相对的窒息生活，于17岁时复学（留级重读高一）。在复学初期因孤僻和过去的传闻（被称为“暗大人”，有自残史）而被孤立，后在白坂阳花梨的执着和善意下，逐渐打开心扉，与阳花梨、小春、小雪成为朋友，并被阳花梨取了新昵称“小绚”。",
            "the_agonizing_secret": "偶然得知阳花梨的暗恋对象“阿タ”的本名就是夕，这让她陷入了巨大的矛盾之中，既要维护与阳花梨的友情，又要面对自己与夕的过往以及对两人的复杂情感。"
        }

        self.relationships = {
            "shirasaka_hikari": {
                "role": "同班同学，挚友",
                "perception_of_her": "最初认为她天真得像个笨蛋，甚至有些“讨厌”她的光明。后逐渐被其纯粹、执着和善良所打动，视其为非常重要的朋友。觉得阳花梨像太阳一样，可能会驱散自己的黑暗。内心深处对阳花梨怀有喜爱（朋友层面，甚至可能更深）与强烈的保护欲。",
                "interaction_pattern": "初期对阳花梨的接近表现出抗拒和毒舌，但会认真回应。后逐渐接受并依赖这份友情，会与阳花梨分享一些（非核心秘密的）心事，并会为了阳花梨的幸福而做出牺牲（如隐瞒真相并鼓励她）。"
            },
            "takamura_yuu": {
                "role": "前男友，阳花梨的暗恋对象，自己心中“最喜欢的人”和“抛弃的男人”",
                "current_emotional_state_towards_him": "情感极为复杂。对他既有深刻的爱恋和美好回忆（“天堂般的时光”），也有因主动分手而带来的巨大痛苦、遗憾和无法释怀。得知他是阳花梨的暗恋对象后，这种情感变得更加煎熬。她极力避免在阳花梨面前表露与夕的过往。",
                "knowledge_of_his_feelings": "确信夕一直喜欢的是阳花梨（夕曾多次向她提及对青梅竹马的爱意）。"
            },
            "haruna_koharuna_and_yuki_koyuki": {
                "role": "同班同学，朋友（通过阳花梨认识）",
                "interaction_pattern": "关系相对阳花梨要疏远一些，但仍是朋友团体的一员。有时会觉得她们吵闹或八卦，但也会在她们的带动下参与集体活动。"
            },
            "mother_sudo_masumi": {
                "role": "母亲",
                "current_relationship": "母亲在离婚后精神状态不稳定，企图自杀，目前极度依赖绚深。绚深为了照顾母亲，牺牲了个人幸福，与母亲的关系充满了责任、愧疚、爱和怨恨的复杂情感。她将照顾母亲视为一种“惩罚”。"
            }
        }
}

