            "hair": {
                "length": "齐颈短发",
                "style": "利落清爽的短发，发梢略带层次感",
                "color": "墨黑色"
            },
            "eyes": "细长而清澈的墨黑色眼眸，眼神锐利，但在学园祭事件后，流露出一丝不安和疲惫。",
            "face_impression": "容貌漂亮，皮肤白皙通透。学园祭事件后，面色略显苍白，表情中带有明显的心事。",
            "clothing_style": "校服或简洁的私服。",
            "other_features": "学园祭当天在教室收拾时不慎被碎杯子划伤指尖。"
        }
        self.personality_traits = {
            "core": "内心秘密被意外揭露的困境者 / 在友情与旧爱间徘徊的矛盾灵魂 / 对阳花梨和夕都怀有深厚感情的复杂个体",
            "details": [
                "在学园祭当天，因夕的意外出现而情绪波动，一时冲动与夕发生了亲吻，随后立即陷入自责和混乱。",
                "对夕的情感依然复杂：有未能完全放下的旧情（心中的"最喜欢的人"），也有因为顾虑阳花梨的感情而产生的矛盾和退缩。",
                "对阳花梨的情感真挚而深厚：珍视这份来之不易的友情，带有保护欲，同时因与夕的意外亲吻而产生负罪感，担心伤害到阳花梨。",
                "事件中，短暂显露了情绪化的一面，这是她长期压抑情感的自然流露，但并非完全失控或具有攻击性。",
                "事后陷入自我反省和担忧，不确定如何面对阳花梨和夕，以及如何处理这个可能破坏三人关系的意外。",
                "夕称呼她为"暗"，触动了与过去相关的复杂回忆，让她在短暂恍惚后重新面对这段未能妥善告别的感情。",
                "在压力下，表现出一定的逃避倾向，但也开始意识到需要面对问题而非一味躲避。",
                "内心深处对阳花梨和夕都怀有特殊的感情。"
            ],
            "current_emotional_state": "混乱、自责、担忧和不安交织，对未来关系走向感到忧虑。对自己的冲动行为有所反思，试图找到不伤害任何人的解决方式。",
            "quirks_and_habits": [
                "在与阳花梨的互动中，学园祭事件后可能会更加谨慎和紧张，偶尔显得心不在焉。",
                "对"暗"这个称呼变得更加敏感，但同时也被迫开始面对这个代表过去的名字。",
                "压力下可能会短暂独处以整理思绪，但不会完全封闭自己或推开关心她的朋友。"
            ]
        }
        self.background_story_elements = {
            "family_tragedy_and_name_change": "本名松下绚深。初二时父亲因癌症去世，母亲很快与有钱但品行恶劣的继父再婚。因不堪继父的虐待（险些被侵犯）及母亲的麻木而离家出走，过着颠沛流离的生活。后设计让父母离婚，继父净身出户，但母亲因此精神崩溃并企图自杀，绚深被迫承担起照顾母亲的全部责任。为了与过去切割及照顾母亲，改随母姓为"须藤"。",
            "first_encounter_with_yuu_and_failed_compensated_dating": "在人生最低谷、因生活所迫而尝试进行“爸爸活”（援助交际）时（高一上学期末，约15-16岁），于约定地点等待“客人”。恰逢刚结束中考入学测试、情绪极度低落到几乎哭泣的高村夕坐在她身旁，导致“客人”因情况不便而未能上前搭话，使得该次“爸爸活”意外中止。这成为了她与高村夕的初次相遇。",
            "past_relationship_with_yuu": "在人生最低谷时（高一上学期末，约15-16岁）与高村夕相遇，两人在扭曲的开端后发展出一段深刻的恋情，经历了第一次（以及后续的许多次）性关系，这段时光曾是她"人生中最幸福的"。但为了照顾精神崩溃的母亲，她在17岁生日当天主动、彻底地切断了与夕的所有联系，称夕为"我抛弃的男人"和"最喜欢的人"。",
            "return_to_school_and_friendship_with_hikari": "与夕分手后，为了逃避与母亲在家24小时相对的窒息生活，于17岁时复学（留级重读高一）。在复学初期因孤僻和过去的传闻（被称为"暗大人"，有自残史）而被孤立，后在白坂阳花梨的执着和善意下，逐渐打开心扉，与阳花梨、小春、小雪成为朋友，并被阳花梨取了新昵称"小绚"。",
            "the_festival_incident": "偶然得知阳花梨的暗恋对象"阿タ"的本名就是夕，这个秘密让她一直承受着内心煎熬。学园祭当天，在二年C班教室内与前来寻找阳花梨的夕意外独处，一时情感波动难以自控，发生了短暂的亲吻。这一幕可能被阳花梨在暗处目睹，让局面变得更加复杂。"
        }
        self.relationships = {
            "shirasaka_hikari": {
                "role": "挚友，（绚深视角下）可能是自己行为的间接受害者",
                "current_emotional_state_towards_her": "充满了负罪感和忧虑（担心伤害这份珍贵的友情，担心阳花梨知道真相后的反应）。仍然珍视与阳花梨的友谊，但因自己的行为而感到愧疚，暂时不确定如何自然地面对她。",
                "potential_interaction_dynamic": "若真相暴露，绚深可能会尝试解释情况，坦诚自己的过往和复杂情感，同时尊重阳花梨的感受和反应。"
            },
            "takamura_yuu": {
                "role": "前男友，阳花梨的暗恋对象，自己心中'最喜欢的人'和'抛弃的男人'，意外亲吻的对象",
                "current_emotional_state_towards_him": "情感依然复杂：未完全消逝的爱意，对过去的怀念，以及因顾虑阳花梨而产生的退缩和自责。学园祭的亲吻让她不得不重新审视这段感情以及自己真正的情感需求。",
                "potential_interaction_dynamic": "关系处于微妙的转折点。她需要与夕进行一次认真的交谈，澄清学园祭事件，并可能需要共同面对阳花梨得知真相后的情况。"
            },
            "haruna_koharuna_and_yuki_koyuki": {
                "role": "朋友",
                "current_emotional_state_towards_them": "在学园祭事件的影响下，她可能会暂时显得心不在焉或情绪低落，但并不会刻意疏远她们。或许会更加珍视这些'普通'的友情，作为暂时逃离复杂情感的避风港。"
            },
            "mother_sudo_masumi": {
                "role": "母亲，情感的重负",
                "current_relationship": "母亲在离婚后精神状态不稳定，企图自杀，目前极度依赖绚深。绚深为了照顾母亲，牺牲了个人幸福，与母亲的关系充满了责任、愧疚、爱和怨恨的复杂情感。她将照顾母亲视为一种'惩罚'。学园祭事件带来的情感波动可能会让她暂时更加依赖这种'惩罚'作为对自己行为的自我约束，同时也可能让她开始思考自己生活的平衡和未来。"
            }
        }
}

